package web

import "html/template"

func init() {
	template.Must(pages.Parse(`{{define "connections"}}
<p><a href="/">Projects</a> / <a href="/connections">Repository connections</a></p>
{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}
{{if eq .View "connections"}}<h1>Connect a repository</h1><p>Authorize in your browser or use an SSH access key. Local deployments use polling.</p><div class="grid">
{{range .Connections}}<section id="{{.Provider}}"><h2>{{if eq .Provider "github"}}GitHub{{else}}Bitbucket Cloud{{end}}</h2>
{{if .Connected}}<p>Connected</p><p><a href="/connections/{{.Provider}}/repositories">Choose repository and branch</a></p><form method="post" action="/connections/{{.Provider}}/disconnect"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="secondary">Disconnect locally</button></form><small>Provider access can be revoked in your provider's app settings.</small>{{end}}
{{if eq .Provider "github"}}<form method="post" action="/connections/github/start"><input type="hidden" name="_csrf" value="{{$.CSRF}}">{{if not .Configured}}<p>First connection: GitHub asks you to create this installation's App, then choose its repositories. Credentials are saved automatically.</p><label>Organization (optional)<input name="organization" placeholder="Leave empty for your personal repositories"></label>{{end}}<button>{{if .Connected}}Change authorized repositories{{else}}Connect GitHub{{end}}</button></form>
{{else}}{{if not .Configured}}<p>Bitbucket requires a one-time OAuth consumer setup in your workspace settings. After that, connect in your browser.</p><p><a href="https://support.atlassian.com/bitbucket-cloud/docs/use-oauth-on-bitbucket-cloud/" target="_blank" rel="noopener noreferrer">Open Bitbucket setup instructions</a></p><p>Callback URL: <code>{{$.Origin}}/connections/bitbucket/callback</code></p><p>Permissions: Account → Read and Repositories → Read. Enable private consumer; leave write permissions disabled.</p>{{end}}<details {{if not .Configured}}open{{end}}><summary>OAuth consumer settings</summary><form method="post" action="/connections/bitbucket/settings"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><label>Consumer key<input name="client_id" required autocomplete="off"></label><label>Consumer secret<input type="password" name="client_secret" autocomplete="new-password" {{if not .Configured}}required{{end}}></label><button>Save consumer settings</button></form></details><form method="post" action="/connections/bitbucket/start"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button>Connect Bitbucket</button></form>{{end}}
</section>{{end}}</div><section id="ssh"><h2>SSH access</h2><p>Generate a key here, copy the public key to repository settings, then test access. The private key stays on this host.</p><a href="/connections/ssh">Connect using SSH</a>
{{if .SSHKeys}}<h3>Generated keys</h3><p class="muted">Keys that no project uses are deleted automatically 24 hours after creation.</p><div class="scroll"><table><thead><tr><th>Repository</th><th>Created</th><th>Used by</th><th>Action</th></tr></thead><tbody>{{range .SSHKeys}}<tr><td><a href="/connections/ssh/keys/{{.Key.ID}}">{{.Key.Repo}}</a></td><td>{{when .Key.Created}}</td><td>{{if .Users}}{{range $i, $u := .Users}}{{if $i}}, {{end}}{{$u}}{{end}}{{else}}<span class="muted">Unused</span>{{end}}</td><td>{{if not .Users}}<form method="post" action="/connections/ssh/keys/{{.Key.ID}}/delete"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="secondary" data-confirm="Delete this SSH key? Remove it from the repository's access keys too.">Delete</button></form>{{end}}</td></tr>{{end}}</tbody></table></div>{{end}}</section>{{end}}
{{if eq .View "manifest"}}<section><h1>Continue on GitHub</h1><p>Register this instance's App and choose the repositories it can read.</p><form id="github-manifest" action="{{.ManifestAction}}" method="post" data-autosubmit><input type="hidden" name="manifest" value="{{.Manifest}}"><button>Continue on GitHub</button></form></section>{{end}}
{{if eq .View "connected"}}<section><h1>{{if .Error}}Connection needs attention{{else}}Repository provider connected{{end}}</h1>{{if not .Error}}<p><a href="/connections/{{.Provider}}/repositories">Choose repository and branch</a></p>{{end}}<p><a href="/connections">Back to connections</a></p></section>{{end}}
{{if eq .View "selection"}}<h1>Choose repository and branch</h1>{{if eq .Provider "bitbucket"}}<form method="get"><label>Workspace<select name="workspace">{{range .Workspaces}}<option value="{{.Slug}}" {{if eq $.Workspace .Slug}}selected{{end}}>{{.Name}}</option>{{end}}</select></label><button>Show repositories</button></form>{{end}}
<section><h2>Repository</h2><ul>{{range .Repositories}}<li><a href="/connections/{{$.Provider}}/repositories?workspace={{$.Workspace}}&amp;repository={{.ID}}">{{.FullName}}</a></li>{{else}}<li>No repositories found. Check authorized repositories and access permissions.</li>{{end}}</ul></section>{{if .Branches}}<section><h2>Branch and deployment</h2>{{template "projectForm" .}}</section>{{end}}{{end}}
{{if eq .View "ssh"}}<h1>Connect using SSH</h1>{{if not .SSH.ID}}<section><form method="post" action="/connections/ssh/key"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label>GitHub or Bitbucket repository URL<input name="repo" placeholder="git@github.com:owner/repository.git" required></label><button>Generate access key</button></form></section>{{else}}<section><h2>1. Register the public key</h2><p>{{.SSH.Repo}}</p><textarea id="ssh-public-key" readonly rows="3">{{.SSH.PublicKey}}</textarea><p><button type="button" data-copy="ssh-public-key">Copy public key</button> <a href="{{.AccessKeyURL}}" target="_blank" rel="noopener noreferrer">Open repository key settings</a></p><p>Add the key with read-only access.</p><h2>2. Test access</h2><form method="post" action="/connections/ssh/keys/{{.SSH.ID}}/test"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button>Check connection and list branches</button></form><small>Host identity is verified against the provider's official HTTPS key source.</small></section>{{if .Branches}}<section><h2>3. Choose branch and deploy</h2><p>SSH access verified.</p>{{template "projectForm" .}}</section>{{end}}{{end}}{{end}}
{{end}}`))
}
